	vesselName: string;
	/**
	* Where the vessel came down: KSP's own recovery-location string (e.g.
	* `"KSC"`, `"Water"`).
	*/
	recoveryLocation: string;
	/**
	* KSP's own recovery-factor display string (e.g. `"100%"`), the payout
	* multiplier for landing precision.
	*/
